var i=`0201-tortilla-espanola`;var o=`world-0201`;var n=`ES`;var l=`southern-europe`;var a=4;var s=31;var r={en:`Tortilla Española`,ua:`Іспанська тортилья`};var d={en:`A traditional Spain dish made with potato, yellow onion, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: картопля, жовта цибуля, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Cook the thinly sliced potatoes and onions slowly in olive oil over medium-low heat until tender, not crisp. Drain off excess oil.`,ua:`Повільно готуйте тонко нарізані картоплю та цибулю в оливковій олії на помірно слабкому вогні до м’якості без хрусткої скоринки. Злийте зайву олію.`,t:[`pan-frying`],m:18,i:[[`potato`,650,`g`],[`yellow-onion`,180,`g`],[`extra-virgin-olive-oil`,95,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:3,i:[[`chicken-egg`,6,`pcs`],[`table-salt`,null,`to_taste`]]},{en:`Return the egg-and-potato mixture to a lightly oiled skillet, cook gently until the base sets, then turn with a plate and finish the other side; the center should be set for a safe egg dish.`,ua:`Перекладіть яєчно-картопляну масу на злегка змащену сковороду, готуйте до схоплення низу, переверніть за допомогою тарілки й допечіть інший бік до безпечної готовності яєць.`,t:[`pan-frying`],m:10,i:[]}];var g={slug:i,id:o,country:`ES`,region:l,servings:4,minutes:31,title:r,text:d,steps:h};export{n as country,g as default,o as id,s as minutes,l as region,a as servings,i as slug,h as steps,d as text,r as title};